"""Common unit conversions used across the pigging telemetry pipeline."""

KM_TO_M = 1000.0
PSI_TO_KPA = 6.89476
MM_TO_M = 0.001


def km_to_m(value_km: float) -> float:
    return value_km * KM_TO_M


def psi_to_kpa(value_psi: float) -> float:
    return value_psi * PSI_TO_KPA


def mm_to_m(value_mm: float) -> float:
    return value_mm * MM_TO_M


def ms_to_s(value_ms: float) -> float:
    return value_ms / 1000.0
